import numpy as np, torch, model
net = model.load()
w=torch.tensor(np.load('contrast_c6_blocks.2.act_k14.npy')).float(); b=-8.0111
def dec(xi,c,dv=None,klo=12,khi=15,dlo=0,dhi=15):
    x=torch.as_tensor(xi).float(); c=torch.as_tensor(c).float(); F=torch.zeros(x.shape[0],dtype=bool)
    for k in range(20):
        t=torch.full((x.shape[0],),1-k/20)
        v,A=net.velocity(x,t,c,('blocks.2.act',),count=False)
        f=(A['blocks.2.act']@w+b>0)
        if dlo<=k<dhi: F|=f
        if dv is not None and klo<=k<khi: v=v+f[:,None].float()*torch.tensor(dv).float()
        x=x-v/20
    return x.numpy(),F.numpy()
xi=np.load('xi.npy'); c=np.load('c.npy')
a0,F0=dec(xi,c)
G=~F0
def score(a1):
    # typicality: nearest baseline non-track action with |dc|<0.03
    Fi=np.where(F0)[0]; ty=[]; nearbad=[]
    for i in Fi:
        m=np.abs(c-c[i])<0.03
        ty.append(np.min(np.linalg.norm(a0[m&G]-a1[i],axis=1)))
        nearbad.append(np.min(np.linalg.norm(a0[m&F0]-a1[i],axis=1)))
    ty=np.array(ty); nb=np.array(nearbad)
    return (ty<nb).mean().round(2), np.quantile(ty,[0.5,0.9]).round(2)
